/* =====================
 — FOLIO — 
By 克劳德(orz)和remige (美工监工）
版本： sillytavern 1.19
   ================== */
/* ━━━━━━━━━━━
   快速设置 
   更改改数字或引号里的字，保留 px (如有）和结尾的" ;"
━━━━━━━━━━ */

/* ① 字体链接（这两行必须在最上面）
   换字体：在字体网站复制新链接替换url('这里'），再改 ② 的字体名 */
@import url('https://fonts.googleapis.com/css2?family=Bodoni+Moda:ital,opsz,wght@0,6..96,400;0,6..96,500;1,6..96,400&family=Newsreader:ital,opsz,wght@0,6..72,400;1,6..72,400&family=Jost:wght@400;500&family=IBM+Plex+Mono&display=swap');  /* 英文字体 */
@import url('https://fonts.googleapis.com/css2?family=Noto+Serif+SC:wght@400;600&display=swap');  /* 中文字体 */

:root {
  /* ② 字体名（需和 ① 链接里的名字一致） */
  --theme-font-cn: 'Noto Serif SC';     /* 中文 */
  --theme-font-title: 'Bodoni Moda';    /* 名字·标题 */
  --theme-font-body: 'Newsreader';      /* 英文正文 */
  --theme-font-ui: 'Jost';              /* 菜单·按钮 */

  /* ③ 左边留白（ 默认 74 / 40   建议 电脑 56–120 · 手机 30–60
*/
  --theme-left-pc: 74px;
  --theme-left-phone: 40px;

  /* ④ 右边留白  默认 48 / 16   建议 电脑 0–96 · 手机 0–28 */
  --theme-text-right-pc: 48px;
  --theme-text-right-phone: 16px;

  /* ⑤ 照片雾化  模糊 默认 2px（0 清晰 · 12 全雾）  白雾 默认 0.20（0 无 · 0.6 很白，不带 px） */
  --theme-fog-blur: 0px;
  --theme-fog-white: 0.20;
}
/* 隐藏聊天头像，只看背景 */
#chat .mes .avatar { display: none !important; }

/* ━━━━━━━━━━━ 快速设置结束，以下是主题本体 ━━━━━━━ */

:root {
  --theme-text-right: var(--theme-text-right-pc);
  --theme-page: #F2F2F0;
  --theme-paper: var(--SmartThemeBotMesBlurTintColor, #fff);
  --theme-paper-user: var(--SmartThemeUserMesBlurTintColor, #F4F4F2);
  --theme-ink: var(--SmartThemeBodyColor, #111);
  --theme-grey: var(--SmartThemeEmColor, #5E5E5B);
  --theme-rule: #D6D6D2;
  --theme-num: #C9C9C5;
  --theme-accent: var(--SmartThemeQuoteColor);
  --theme-soft: color-mix(in srgb, var(--SmartThemeQuoteColor) 16%, transparent);
  --theme-display: var(--theme-font-title), var(--theme-font-cn), 'Songti SC', serif;
  --theme-text: var(--theme-font-body), var(--theme-font-cn), 'Songti SC', serif;
  --theme-ui: var(--theme-font-ui), var(--theme-font-cn), sans-serif;
  --theme-mono: 'IBM Plex Mono', ui-monospace, monospace;
  --mainFontFamily: var(--theme-ui);      /* UI face; chat text sets its own */
  --interactable-outline-color: var(--SmartThemeQuoteColor);
  /* ST's fixed "white/black at alpha" globals assume a dark theme; on paper they become ink tints.
     (Core and extensions use them for faint text, hover fills and input fills.) */
  --white20a: rgba(17, 17, 17, .08);
  --white30a: rgba(17, 17, 17, .12);
  --white50a: rgba(17, 17, 17, .48);
  --white60a: rgba(17, 17, 17, .6);
  --white70a: rgba(17, 17, 17, .72);
  --black30a: rgba(17, 17, 17, .03);
  --black50a: rgba(17, 17, 17, .06);   /* select chips, Quick Reply editor, shadows */
  --black60a: rgba(17, 17, 17, .08);
  --black70a: rgba(17, 17, 17, .10);   /* dropdown options, code, popup dims */
  --grey30: #ECECE9;
  /* message geometry */
  --theme-m: 30px;          /* page margin inside each message */
  --theme-photo: 250px;     /* height of the photograph */
  --theme-numcol: var(--theme-left-pc);     /* folio-number column */
}

