/* ── Ground: the page is paper; your background only shows inside the photographs ── */
body { background: var(--theme-page); text-autospace: normal; }
#sheld { box-shadow: 0 0 0 100vmax var(--theme-page); }
#chat {
  background: transparent !important;
  backdrop-filter: none !important; -webkit-backdrop-filter: none !important;
  text-shadow: none !important;
  padding: 0 !important;
  scrollbar-color: var(--theme-ink) var(--theme-paper);
  scrollbar-width: thin;
}
#chat::-webkit-scrollbar-track { background: var(--theme-paper); }
#chat::-webkit-scrollbar-thumb { background: var(--theme-ink); border-radius: 0; }
#chat::after { content: ''; flex: 1 0 0; min-height: 0; background: var(--theme-paper); }

/* sharp corners everywhere */
#top-bar, #send_form, #form_sheld, .drawer-content, .options-content, #extensionsMenu, .list-group,
.menu_button, .popup, #send_textarea, .text_pole, .mes, .mes_block, .mes_buttons, .extraMesButtons,
.mes_reasoning_details, .swipes-counter, .mes_edit_buttons .menu_button { border-radius: 0 !important; }

/* ── Top bar ── */
#top-bar {
  background: var(--theme-paper); box-shadow: none; border-bottom: 1px solid var(--theme-ink);
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
#top-settings-holder { gap: 2px; }
#top-settings-holder .drawer-icon { width: 44px; height: 34px; display: flex; color: var(--theme-ink); opacity: .78; --theme-ic: 21px; transition: color var(--animation-duration-2x), opacity var(--animation-duration-2x); }
#top-settings-holder .drawer-toggle:hover .drawer-icon { opacity: 1; color: var(--theme-accent); }
#top-settings-holder .drawer-icon.openIcon { opacity: 1; color: var(--theme-accent); box-shadow: inset 0 -2px 0 var(--theme-accent); }

/* ═══ PANELS — every top-bar drawer, popups, chat history (UI Background) ═══ */
.drawer-content, #character_popup, .popup, #select_chat_popup, #completion_prompt_manager_popup {
  /* your UI Background tint, laid on solid paper so the chat never shows through */
  background: linear-gradient(var(--SmartThemeBlurTintColor), var(--SmartThemeBlurTintColor)), var(--theme-paper);
  border: 1px solid var(--theme-ink); border-radius: 0;
  box-shadow: 0 28px 56px -36px rgba(0, 0, 0, .45);
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
.drawer-content { padding: 14px 18px; }
.drawer-content h3, .popup h3, #character_popup h3 {
  font-family: var(--theme-display); font-weight: 400; font-size: calc(var(--mainFontSize) * 1.55); letter-spacing: -.005em; margin: 4px 0 10px;
}
.drawer-content h4, .drawer-content h5 {
  font-family: var(--theme-ui); font-weight: 500; font-size: calc(var(--mainFontSize) * .75); letter-spacing: .24em; text-transform: uppercase;
}
.drawer-content small, .toggle-description, .range-block-title small { color: var(--theme-grey); }
/* section headers in User Settings and every extension: a ruled caption, not a gradient bar */
.standoutHeader, #user-settings-block h4,
#extensions_settings .inline-drawer-header, #extensions_settings2 .inline-drawer-header {
  background-image: none !important; background-color: transparent; border: 0; border-bottom: 1px solid var(--theme-ink); border-radius: 0;
  padding: 8px 2px; font-family: var(--theme-ui); font-weight: 500; font-size: calc(var(--mainFontSize) * .78); letter-spacing: .22em; text-transform: uppercase;
}
.standoutHeader:hover { filter: none; color: var(--theme-accent); }
.standoutHeader ~ .inline-drawer-content, .inline-drawer-content { background-color: transparent; border: 0; border-radius: 0; }
.inline-drawer-icon { color: var(--theme-ink); }
.drawer-content hr, .popup hr { border: 0; height: 1px; background: var(--theme-rule); opacity: 1; }

/* text fields inside every panel and popup: white boxes, folio (core fills bare textareas/inputs with --black30a) */
.drawer-content :is(textarea, input[type="text"], input[type="search"], input[type="number"], input[type="url"], input[type="password"], select),
.popup :is(textarea, input[type="text"], input[type="number"], select), #character_popup :is(textarea, input[type="text"], select) {
  background-color: var(--theme-paper); border: 1px solid var(--theme-rule); border-radius: 0; color: var(--theme-ink);
}
.drawer-content :is(textarea, input, select):focus { border-color: var(--theme-accent); outline: none; }
.drawer-content textarea, .popup textarea, #character_popup textarea { font-family: var(--theme-text); font-size: calc(var(--mainFontSize) * 1.05); line-height: 1.6; }
/* dropdown + multi-select options: core paints unpicked ones near-black */
select option, select option:not(:checked) { background-color: var(--theme-paper); color: var(--theme-ink); }
select option:checked { background: linear-gradient(var(--theme-soft), var(--theme-soft)), var(--theme-paper); color: var(--theme-ink); }
select option[disabled]:not(:checked) { color: var(--theme-grey); }
/* switched-off things: core darkens them to muddy grey (brightness .5); here they just go quiet */
input:disabled, textarea:disabled, #AdvancedFormatting .disabled { filter: none; opacity: .5; }
.select2-container .select2-results .select2-results__option--disabled { filter: none; opacity: .45; }
.drawer-content code, .popup code { background-color: var(--theme-page); color: var(--theme-ink); border-color: var(--theme-rule); border-radius: 0; }

/* Character Management › favourites row (hotswap): all 25 ST loads, one scrollable strip */
#HotSwapWrapper { min-width: 0; justify-content: flex-start; }
#HotSwapWrapper .hotswap {
  --avatar-base-width: 54px; --avatar-base-height: 54px;
  flex-wrap: nowrap; justify-content: flex-start; gap: 10px; max-height: none; margin: 4px 0;
  overflow-x: auto; overflow-y: hidden; padding: 6px 18px 10px 2px; scroll-snap-type: x proximity;
  scrollbar-width: thin; scrollbar-color: var(--theme-ink) transparent;
  -webkit-mask: linear-gradient(90deg, #000 calc(100% - 28px), transparent); mask: linear-gradient(90deg, #000 calc(100% - 28px), transparent);
}
#HotSwapWrapper .hotswap::-webkit-scrollbar { height: 3px; }
#HotSwapWrapper .hotswap .avatar { flex: 0 0 auto; margin: 0; opacity: 1; scroll-snap-align: start; }
#HotSwapWrapper .hotswap .avatar img {
  border: 1px solid var(--theme-rule); box-shadow: none; filter: grayscale(.4) contrast(.95);
  transition: filter var(--animation-duration-2x), border-color var(--animation-duration-2x);
}
#HotSwapWrapper .hotswap .avatar:hover img { filter: none; border-color: var(--theme-accent); }

/* AI Response Configuration › prompt list: rows on folios; switched-off prompts readable, just quieter */
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt,
#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  border: 0; border-bottom: 1px solid var(--theme-rule); border-radius: 0; background: none;
}
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name,
#completion_prompt_manager #completion_prompt_manager_list .completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name .prompt-manager-inspect-action {
  color: var(--theme-grey); opacity: .75;
}
#completion_prompt_manager .completion_prompt_manager_header { color: var(--theme-grey); }
/* core gives just this one word a black drop-shadow; nothing else in the theme has one */
#completion_prompt_manager .completion_prompt_manager_header_advanced span { filter: none; }

/* panels open with a short fade-down instead of ST's height grow (smoother on phones; Reduced Motion zeroes it) */
@keyframes theme-panel-in { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
.drawer-content.openDrawer { transition: none; animation: theme-panel-in var(--animation-duration-2x) ease-out both; }
.fillLeft.openDrawer, .fillRight.openDrawer { animation-name: theme-panel-in; }

/* ═══ CONTROLS ═══ */
/* icon-only buttons carry Font Awesome classes on the button itself: never change their font */
.menu_button {
  filter: none; border-radius: 0; background-color: var(--theme-paper); border: 1px solid var(--theme-ink); color: var(--theme-ink);
  font-size: calc(var(--mainFontSize) * .85); letter-spacing: .04em;
  transition: background-color var(--animation-duration), color var(--animation-duration);
}
.menu_button:not(.fa-solid):not(.fa-regular):not(.fa-brands) { font-family: var(--theme-ui); }
.menu_button:not(.disabled):not([disabled]):hover, .menu_button.active, .menu_button.toggled {
  background-color: var(--theme-ink); color: var(--theme-paper);
}
.menu_button.disabled, .menu_button[disabled] { filter: none; opacity: .4; }
.menu_button.popup-button-ok, .menu_button.redWarningBG { background-color: var(--theme-accent); border-color: var(--theme-accent); color: #fff; }
.text_pole, select, .select2-container .select2-selection, .select2-dropdown {
  background-color: var(--theme-paper); border: 1px solid var(--theme-rule); border-radius: 0; color: var(--theme-ink);
  font-family: var(--theme-ui);
}
.text_pole:focus, .text_pole:focus-visible, select:focus { border-color: var(--theme-accent); outline: none; }
input[type="checkbox"] { border-radius: 0; background-color: transparent; border: 1px solid var(--theme-ink); }
input[type="checkbox"]:checked { background-color: var(--theme-accent); }
.neo-range-input, .range-block-counter input { border-radius: 0 !important; }
input[type="range"]:not(.neo-range-slider)::-webkit-slider-thumb { border-radius: 0; background: var(--theme-accent); }
.tag {
  border-radius: 0; border: 1px solid var(--theme-rule); background-color: transparent;
  font-family: var(--theme-ui); font-size: calc(var(--mainFontSize) * .78); letter-spacing: .06em; padding: 0 .45rem;
}
::-webkit-scrollbar-thumb:vertical, ::-webkit-scrollbar-thumb:horizontal { background-color: var(--theme-ink); border-radius: 0; }
::-webkit-scrollbar { width: .45rem; }

/* character list + personas: an index, one folio per entry */
.character_select, .group_select, .bogus_folder_select, .avatar-container {
  --avatar-base-width: 46px; --avatar-base-height: 46px;
  border-radius: 0; border-bottom: 1px solid var(--theme-rule); padding: 10px 6px; margin: 0;
}
.character_select:hover, .group_select:hover, .avatar-container:hover { background-color: var(--theme-page); }
.character_select .ch_name, .group_select .ch_name, .avatar-container .ch_name {
  font-family: var(--theme-display); font-size: calc(var(--mainFontSize) * 1.2); font-weight: 400;
}
/* portraits: crop from the upper part so foreheads aren't cut, and sit level with the name */
body[class] .avatar img { object-position: 50% 15%; }
.character_select .avatar, .group_select .avatar, .bogus_folder_select .avatar, .avatar-container .avatar { align-self: flex-start; margin-top: 3px; }
body:not(.big-avatars) :is(.character_select, .group_select, .bogus_folder_select) { --avatar-base-width: 58px; --avatar-base-height: 58px; }
/* grid view (characters + personas): portrait and name centred on one axis, no half-width folios */
#user_avatar_block.gridView .avatar-container,
body.charListGrid #rm_print_characters_block :is(.character_select, .group_select, .bogus_folder_select) { align-items: center; border-bottom: 0; padding: 8px 4px; }
#user_avatar_block.gridView .avatar-container .avatar,
body.charListGrid #rm_print_characters_block :is(.character_select, .group_select, .bogus_folder_select) .avatar { align-self: center; margin-top: 0; }
#user_avatar_block.gridView .avatar-container .ch_name,
body.charListGrid #rm_print_characters_block .ch_name { text-align: center; margin-top: 4px; }
.avatar.is_fav { outline-color: var(--theme-accent); }   /* default persona: accent ring, not core's gold */
#user_avatar_block .avatar_upload { border-radius: 0; }
/* Persona Management › current persona: the name in the display face, every button one size (extensions' too) */
#persona_controls .persona_name {
  font-family: var(--theme-display); font-size: calc(var(--mainFontSize) * 1.5); font-weight: 400;
  letter-spacing: 0; text-transform: none; color: var(--theme-ink); opacity: 1;
}
#persona_controls .buttons_block { gap: 5px; }
#persona_controls .buttons_block > * {
  box-sizing: border-box; width: 34px; height: 34px; min-width: 0; min-height: 0; padding: 0; margin: 0; flex: none;
  display: flex; align-items: center; justify-content: center; font-size: 15px; line-height: 1;
}
#persona_controls .buttons_block > * > :is(i, svg, img) { font-size: 15px; width: auto; height: auto; max-width: 18px; max-height: 18px; margin: 0; padding: 0; }
.character_select.is_fav .ch_name, .ch_fav_icon { color: var(--theme-accent); }
.character_select.is_fav .avatar { outline-color: var(--theme-accent); }
.ch_description { font-family: var(--theme-text); font-style: italic; color: var(--theme-grey); }
.avatar-container.selected { background-color: var(--theme-page); }
.avatar-container.selected .ch_name { color: var(--theme-accent); }
.bg_example { border-radius: 0; border: 1px solid var(--theme-rule); }
.bg_example_img { border-radius: 0; }
.BGSampleTitle { font-family: var(--theme-ui); font-size: calc(var(--mainFontSize) * .72); letter-spacing: .08em; }

/* popups */
/* ST's loading screen and other "transparent" popups: no card, no border around them */
.popup.transparent_dialogue_popup { background: none; border: 0; box-shadow: none; }
#preloader { background-color: var(--theme-page); backdrop-filter: none; -webkit-backdrop-filter: none; }
.popup[open]::backdrop { background-color: color-mix(in srgb, var(--theme-page) 70%, transparent); }

/* ═══ NOTIFICATIONS ═══ */
body #toast-container > div {
  background-color: var(--theme-paper); color: var(--theme-ink); border: 1px solid var(--theme-ink); border-radius: 0; opacity: 1;
  box-shadow: 0 18px 36px -24px rgba(0, 0, 0, .45); font-family: var(--theme-ui); background-position: 16px center; filter: grayscale(1) contrast(1.2);
}
body #toast-container .toast-error { border-color: var(--theme-accent); color: var(--theme-accent); filter: none; }

/* ═══ MESSAGES ═══════════════════════════════════════════════ */
#chat .mes {
  --avatar-base-width: 128px; --avatar-base-height: 128px;
  display: grid !important;
  grid-template-columns: var(--theme-m) minmax(var(--theme-numcol), max-content) 24px minmax(0, 1fr) var(--theme-m); /* number column grows for 4-digit+ numbers */
  grid-template-rows: var(--theme-m) auto auto auto auto auto auto auto auto var(--theme-m);
  padding: 0 !important; margin: 0;
  background: var(--theme-paper);
  color: var(--theme-ink);
}
/* unwrap ST's containers so every part can be placed on the page grid */
#chat .mes .mesAvatarWrapper,
#chat .mes .mes_block,
#chat .mes .ch_name { display: contents !important; }
#chat .mes .del_checkbox, #chat .mes .for_checkbox { grid-row: 2; grid-column: 2; }

/* the folio number + its vertical folio */
#chat .mes .mesIDDisplay {
  grid-row: 3; grid-column: 2; align-self: start;
  font-family: var(--theme-display); font-size: 30px; line-height: .9; font-weight: 400; /* one size for everyone: fits 4-digit numbers */
  color: var(--theme-num);
  /* hide the "#": shift it out of a clipped box */
  overflow: visible; clip-path: inset(0 -60px 0 0); white-space: nowrap; text-align: left; text-indent: -.66em; padding-top: 4px; /* clip only the left (the #), so 3-digit numbers can spill right */
  opacity: 1; display: block;
}
#chat .mes::after {
  content: ''; grid-row: 3 / 10; grid-column: 3; justify-self: start; width: 1px; background: var(--theme-rule);
}
#chat .mes .mes_timer, #chat .mes .tokenCounterDisplay {
  grid-column: 2; align-self: start; font-family: var(--theme-mono); font-size: 10px; letter-spacing: .04em;
  color: var(--theme-grey); text-align: left; padding: 0; margin: 0; display: block;
}
#chat .mes .mes_timer { grid-row: 4; margin-top: 10px; }
#chat .mes .tokenCounterDisplay { grid-row: 5; margin-top: 2px; }

/* headline: name, time, model */
#chat .mes .ch_name > .flex-container {
  grid-row: 3; grid-column: 4; display: flex; flex-wrap: wrap; align-items: baseline; gap: 4px 14px;
  padding: 2px 0 10px; min-width: 0;
}
#chat .mes .ch_name > .flex-container > .flex-container { display: contents; }
#chat .mes .name_text {
  font-family: var(--theme-display); font-size: 32px; line-height: 1; font-weight: 400; letter-spacing: -.005em;
  color: var(--theme-ink); flex: 0 0 auto;
}
#chat .mes .timestamp {
  font-family: var(--theme-ui); font-size: 10.5px; font-weight: 500; letter-spacing: .22em; text-transform: uppercase;
  color: var(--theme-grey); display: inline;
}
#chat .mes .timestamp-icon { width: 13px; height: 13px; opacity: .7; filter: grayscale(1); align-self: center; }
#chat .mes .mes_ghost { font-size: 0; color: var(--theme-grey); --theme-ic: 14px; }

/* reasoning, text, media, swipes */
#chat .mes .mes_reasoning_details { grid-row: 4 / 6; grid-column: 4; margin: 0 0 12px !important; padding: 0 var(--theme-text-right) 0 0; align-self: start; justify-self: stretch; min-width: 0; width: 100%; box-sizing: border-box; }
#chat .mes .mes_text { grid-row: 6; grid-column: 4; }
#chat .mes .mes_media_wrapper { grid-row: 7; grid-column: 4; }
#chat .mes .mes_file_wrapper, #chat .mes .mes_bias { grid-row: 8; grid-column: 4; }

#chat .mes .mes_text {
  font-family: var(--theme-text); font-size: calc(var(--mainFontSize) * 1.13); line-height: 1.85; font-weight: 400;
  padding: 0 var(--theme-text-right) 0 0; text-wrap: pretty; overflow-wrap: break-word; line-break: strict;
}
#chat .mes .mes_text p { margin: 0 0 .85em; }
#chat .mes .mes_text p:last-child { margin-bottom: 0; }
#chat .mes .mes_text em, #chat .mes .mes_text i { color: var(--theme-grey); font-style: italic; opacity: 1; border: 0; font-weight: inherit; }
#chat .mes .mes_text q { color: var(--theme-accent); }
#chat .mes .mes_text q em, #chat .mes .mes_text q i { color: inherit; }
#chat .mes .mes_text a { color: var(--theme-accent); text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px; }
#chat .mes .mes_text blockquote { margin: .6em 0; padding-left: 16px; border-left: 1px solid var(--theme-ink); }
#chat .mes .mes_text hr { border: 0; border-top: 1px solid var(--theme-rule); opacity: 1; }
#chat .mes .mes_text code { border-radius: 0; background: var(--theme-page); color: var(--theme-ink); border-color: var(--theme-rule); }

#chat .mes .mes_reasoning_summary { padding: 0; margin-right: 0 !important; }
#chat .mes .mes_reasoning_header {
  display: flex; align-items: center; gap: 10px; padding: 7px 0; border-top: 1px solid var(--theme-rule); border-bottom: 1px solid var(--theme-rule);
  background: none; border-radius: 0; width: auto; margin: 0;
}
#chat .mes .mes_reasoning_header::before { content: ''; width: 6px; height: 6px; background: var(--theme-accent); flex: none; }
#chat .mes .mes_reasoning_header_title { font-family: var(--theme-ui); font-size: 10.5px; font-weight: 500; letter-spacing: .22em; text-transform: uppercase; color: var(--theme-grey); flex: 1; }
#chat .mes .mes_reasoning_header { flex: 1; padding-right: 30px; }
#chat .mes .mes_reasoning_arrow { --theme-ic: 14px; width: 14px; height: 14px; color: var(--theme-grey); }
#chat .mes .mes_reasoning { font-family: var(--theme-text); font-style: italic; color: var(--theme-grey); padding: 10px 0 0; border: 0; background: none; }

#chat .mes .swipe_left, #chat .mes .swipeRightBlock {
  position: relative !important; inset: auto !important; grid-row: 9; grid-column: 4; align-self: center; margin-top: 14px;
}
/* the left chevron's stroke starts 14px into its box: pull it back so it lines up with the paragraph */
#chat .mes .swipe_left { justify-self: start; width: 34px; height: 34px; box-sizing: border-box; padding: 0; margin: 14px 0 0 -14px; opacity: .85; --theme-ic: 16px; color: var(--theme-ink); }
#chat .mes .swipeRightBlock {
  justify-self: start; margin-left: 20px; display: flex !important; flex-direction: row-reverse !important; align-items: center; height: 34px; pointer-events: auto;
}
#chat .mes .swipe_right { width: 34px; height: 34px; box-sizing: border-box; padding: 0; margin: 0; opacity: .85; --theme-ic: 16px; color: var(--theme-ink); }
#chat .mes .swipes-counter {
  opacity: 1; min-width: 0; line-height: 34px; height: 34px; margin: 0; display: flex; align-items: center; align-self: center; padding: 0 6px; font-family: var(--theme-mono); font-size: 11px; letter-spacing: .18em; color: var(--theme-accent);
}
#chat .mes .swipe_left:hover, #chat .mes .swipe_right:hover { color: var(--theme-accent); opacity: 1; }
#chat .mes .swipes-counter { padding: 0 4px; }
/* first swipe: no left arrow, so the counter starts right at the paragraph edge */
#chat .mes:is(:not(.swipes_visible), :has(.swipe_left[hidden])) .swipeRightBlock { margin-left: 0; }
#chat .mes:is(:not(.swipes_visible), :has(.swipe_left[hidden])) .swipes-counter { padding-left: 0; }

body:not(.swipeAllMessages) #chat .mes:not(.last_mes) :is(.swipe_left, .swipeRightBlock) { display: none !important; }

/* ── the tools: hidden until you point at (or tap) a message ── */
#chat .mes .mes_buttons, #chat .mes .mes_edit_buttons {
  grid-row: 3; grid-column: 4; justify-self: end; align-self: start; z-index: 3;
  display: flex; align-items: center; gap: 0; padding: 0; margin: 0;
  background: var(--theme-paper); border: 1px solid var(--theme-ink);
  opacity: 0; pointer-events: none; transition: opacity var(--animation-duration-2x);
}
#chat .mes .mes_edit_buttons { display: none; }
#chat .mes .mes_button, #chat .mes .mes_edit_buttons .menu_button {
  width: 34px; height: 34px; box-sizing: border-box; margin: 0; padding: 0; opacity: 1; color: var(--theme-ink); --theme-ic: 16px;
  font-size: 15px; line-height: 34px; text-align: center; /* any Font Awesome button an extension adds: same box, same size */
  background: none; border: 0; filter: none;
}
#chat .mes .mes_button:hover, #chat .mes .mes_edit_buttons .menu_button:hover { color: var(--theme-accent); background: var(--theme-page); }
#chat .mes .extraMesButtons { gap: 0; padding: 0; border-right: 1px solid var(--theme-rule); }
#chat .mes .extraMesButtons.visible + .mes_bookmark, #chat .mes:has(.extraMesButtons.visible) .mes_edit { border-left: 0; }
#chat .mes .timestamp, #chat .mes .timestamp-icon, #chat .mes .mes_timer, #chat .mes .tokenCounterDisplay { opacity: 0; transition: opacity var(--animation-duration-2x); }
#chat .mes:hover :is(.mes_buttons, .timestamp, .timestamp-icon, .mes_timer, .tokenCounterDisplay),
#chat .mes:focus-within :is(.mes_buttons, .timestamp, .timestamp-icon, .mes_timer, .tokenCounterDisplay),
#chat .mes:has(.extraMesButtons.visible) :is(.mes_buttons, .timestamp, .timestamp-icon, .mes_timer, .tokenCounterDisplay) { opacity: 1; pointer-events: auto; }
#chat .mes .timestamp-icon { opacity: 0; }
#chat .mes:hover .timestamp-icon, #chat .mes:has(.extraMesButtons.visible) .timestamp-icon { opacity: .7; }
/* while editing */
#chat .mes:has(.edit_textarea) .mes_edit_buttons { display: flex; opacity: 1; pointer-events: auto; }
#chat .mes:has(.edit_textarea) .mes_buttons { display: none; }
#chat .mes .mes_edit_delete { border-left: 1px solid var(--theme-rule) !important; border-right: 1px solid var(--theme-rule) !important; }
#chat .mes .edit_textarea { font-family: var(--theme-text); font-size: calc(var(--mainFontSize) * 1.1); line-height: 1.8; border: 1px solid var(--theme-ink); border-radius: 0; background: var(--theme-paper); color: var(--theme-ink); }

/* ═══ CHARACTER MESSAGES: the photograph ═════════════════════ */
#chat .mes[is_user="false"]:not(.smallSysMes) {
  grid-template-rows: var(--theme-m) var(--theme-photo) 22px auto auto auto auto auto auto auto var(--theme-m);
  /* paint the page around the photograph, leave the photograph open */
  background:
    linear-gradient(var(--theme-paper), var(--theme-paper)) 0 0 / 100% calc(var(--theme-m) + 1px) no-repeat,
    linear-gradient(var(--theme-paper), var(--theme-paper)) 0 var(--theme-m) / var(--theme-m) var(--theme-photo) no-repeat,
    linear-gradient(var(--theme-paper), var(--theme-paper)) 100% var(--theme-m) / var(--theme-m) var(--theme-photo) no-repeat,
    linear-gradient(var(--theme-paper), var(--theme-paper)) 0 calc(var(--theme-m) + var(--theme-photo) - 1px) / 100% 100% no-repeat;
}
#chat .mes[is_user="false"]:not(.smallSysMes)::before {
  content: ''; grid-row: 2; grid-column: 2 / 5; height: var(--theme-photo); align-self: start; z-index: 0; pointer-events: none;
  backdrop-filter: blur(var(--theme-fog-blur)) saturate(.5) brightness(1.08) contrast(.92);
  -webkit-backdrop-filter: blur(var(--theme-fog-blur)) saturate(.5) brightness(1.08) contrast(.92);
  background: linear-gradient(rgba(255,255,255,calc(var(--theme-fog-white) * .36)), rgba(255,255,255,var(--theme-fog-white)));
  box-shadow: inset 0 0 0 1px var(--theme-ink);
}
/* the portrait, set into the photograph like a cover */
#chat .mes[is_user="false"]:not(.smallSysMes) .avatar {
  grid-row: 2; grid-column: 2 / 5; place-self: center; z-index: 1; flex: none; margin: 0;
}
/* no frame, no shadow: the sharp picture simply dissolves into the fog at its edges */
#chat .mes[is_user="false"]:not(.smallSysMes) .avatar img {
  border: 0; box-shadow: none; object-position: 50% 14%;
  --theme-feather: transparent 0, rgba(0, 0, 0, .35) 4%, rgba(0, 0, 0, .8) 9%, #000 14%, #000 86%, rgba(0, 0, 0, .8) 91%, rgba(0, 0, 0, .35) 96%, transparent 100%;
  -webkit-mask-image: linear-gradient(90deg, var(--theme-feather)), linear-gradient(180deg, var(--theme-feather));
  mask-image: linear-gradient(90deg, var(--theme-feather)), linear-gradient(180deg, var(--theme-feather));
  -webkit-mask-composite: source-in; mask-composite: intersect;
}
/* Avatar Style: Circle — feather the round edge instead */
body:not(.square-avatars):not(.rounded-avatars):not(.big-avatars) #chat .mes[is_user="false"]:not(.smallSysMes) .avatar img {
  -webkit-mask-image: radial-gradient(closest-side, #000 74%, rgba(0, 0, 0, .8) 84%, rgba(0, 0, 0, .35) 93%, transparent 100%);
  mask-image: radial-gradient(closest-side, #000 74%, rgba(0, 0, 0, .8) 84%, rgba(0, 0, 0, .35) 93%, transparent 100%);
  -webkit-mask-composite: source-over; mask-composite: add;
}
/* caption strip under the photograph */
#chat .mes[is_user="false"]:not(.smallSysMes) .mesIDDisplay,
#chat .mes[is_user="false"]:not(.smallSysMes) .ch_name > .flex-container,
#chat .mes[is_user="false"]:not(.smallSysMes) .mes_buttons,
#chat .mes[is_user="false"]:not(.smallSysMes) .mes_edit_buttons { grid-row: 4; }
#chat .mes[is_user="false"]:not(.smallSysMes) .mes_timer { grid-row: 5; }
#chat .mes[is_user="false"]:not(.smallSysMes) .tokenCounterDisplay { grid-row: 6; }
#chat .mes[is_user="false"]:not(.smallSysMes) .mes_reasoning_details { grid-row: 5 / 7; }
#chat .mes[is_user="false"]:not(.smallSysMes) .mes_text { grid-row: 7; }
#chat .mes[is_user="false"]:not(.smallSysMes) .mes_media_wrapper { grid-row: 8; }
#chat .mes[is_user="false"]:not(.smallSysMes) :is(.mes_file_wrapper, .mes_bias) { grid-row: 9; }
#chat .mes[is_user="false"]:not(.smallSysMes) :is(.swipe_left, .swipeRightBlock) { grid-row: 10; }
#chat .mes[is_user="false"]:not(.smallSysMes)::after { grid-row: 4 / 11; }
/* the tools sit on the photograph's top corner */
#chat .mes[is_user="false"]:not(.smallSysMes) .mes_buttons,
#chat .mes[is_user="false"]:not(.smallSysMes) .mes_edit_buttons { grid-row: 2; grid-column: 2 / 5; justify-self: end; align-self: start; margin: 12px; }

/* ═══ YOUR MESSAGES: a caption, no photograph ════════════════ */
#chat .mes[is_user="true"] { background: var(--theme-paper-user); grid-template-rows: 22px auto auto auto auto auto auto auto auto 26px; }
#chat .mes[is_user="true"] .avatar { display: none; }
#chat .mes[is_user="true"] .mesIDDisplay { grid-row: 2 / 4; }
/* right padding keeps the date clear of the tools; if both don't fit, the date drops under the name */
#chat .mes[is_user="true"] .ch_name > .flex-container { grid-row: 2; padding-bottom: 6px; padding-right: 128px; }
/* your name: underlined in the accent colour */
#chat .mes[is_user="true"] .name_text {
  font-family: var(--theme-display); font-size: 26px; font-weight: 400; letter-spacing: 0; text-transform: none;
  display: inline-block; text-decoration: underline 2px var(--theme-accent); text-underline-offset: .24em; text-decoration-skip-ink: none;
}
#chat .mes[is_user="true"] .mes_timer { grid-row: 4; }
#chat .mes[is_user="true"] .tokenCounterDisplay { grid-row: 4; margin-top: 0; }
#chat .mes[is_user="true"] .mes_text { grid-row: 3; grid-column: 4; }
/* same 12px inset as the character's tools on the photograph, so both line up on the right */
#chat .mes[is_user="true"] .mes_buttons, #chat .mes[is_user="true"] .mes_edit_buttons { grid-row: 2; margin-right: 12px; }
#chat .mes[is_user="true"]::after { grid-row: 2 / 10; }
#chat .mes[is_user="true"] + .mes[is_user="false"], #chat .mes[is_user="false"] + .mes[is_user="true"] { border-top: 1px solid var(--theme-rule); }

/* system / narrator lines */
#chat .mes.smallSysMes { display: block !important; padding: 14px var(--theme-m) !important; border-top: 1px solid var(--theme-rule); }
#chat .mes.smallSysMes .mes_text { font-family: var(--theme-ui); font-size: 12px; letter-spacing: .08em; color: var(--theme-grey); text-align: center; }

/* ═══ INPUT BAR ══════════════════════════════════════════════ */
#form_sheld { background: var(--theme-paper); margin-top: 0; }
#send_form {
  background: var(--theme-paper) !important; border: 0; border-top: 1px solid var(--theme-ink);
  backdrop-filter: none; -webkit-backdrop-filter: none; padding: 4px 6px;
}
#leftSendForm, #rightSendForm { gap: 2px; }
#leftSendForm > div, #rightSendForm > div { color: var(--theme-ink); --theme-ic: 21px; opacity: .9; }
#extensionsMenuButton { color: var(--theme-grey) !important; }
#send_textarea {
  font-family: var(--theme-text); font-size: calc(var(--mainFontSize) * 1.07); line-height: 1.6; color: var(--theme-ink);
  background: transparent; border: 0; border-bottom: 1px solid var(--theme-rule); margin: 6px 8px; padding: 6px 2px;
  transition: border-color var(--animation-duration-2x);
}
#send_textarea::placeholder { color: var(--theme-grey); font-style: italic; opacity: .8; }
#send_textarea:focus { border-bottom-color: var(--theme-accent); outline: none; box-shadow: none; }
#send_but { color: var(--theme-accent) !important; opacity: 1 !important; --theme-ic: 23px !important; }
#leftSendForm > div:hover, #rightSendForm > div:hover { color: var(--theme-accent); opacity: 1; }
/* continue / impersonate only while the box is empty; send only once you type */
#send_textarea:placeholder-shown ~ #rightSendForm #send_but { display: none !important; }
#send_textarea:not(:placeholder-shown) ~ #rightSendForm :is(#mes_continue, #mes_impersonate) { display: none !important; }

#options { border: 0 !important; background: none !important; box-shadow: none !important; backdrop-filter: none !important; }
/* Quick Replies: folded away until you use the send bar (tap / focus / hover), then they slide open.
   The short delay on closing lets a tap on a reply land before it folds. */
#qr--bar {
  max-height: 0; opacity: 0; overflow: hidden; padding: 0 6px; order: 1;
  transition: max-height 220ms ease 400ms, opacity 160ms ease 400ms;
}
#send_form:is(:focus-within, :hover) #qr--bar { max-height: 30vh; opacity: 1; overflow-x: auto; padding: 4px 6px 6px; transition-delay: 0s; }
#qr--bar > .qr--buttons { display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; width: 100%; }
#qr--bar .qr--button {
  border-radius: 0; border: 1px solid var(--theme-rule); background: var(--theme-paper); color: var(--theme-ink);
  font-family: var(--theme-ui); font-size: calc(var(--mainFontSize) * .82); letter-spacing: .04em; padding: 3px 10px;
}
#qr--bar .qr--button:hover { border-color: var(--theme-ink); color: var(--theme-accent); }
/* extension buttons that keep Font Awesome glyphs: same size as the folio set */
#leftSendForm > div, #rightSendForm > div { font-size: 19px; }

/* ═══ ☰ OPTIONS + ✦ EXTENSIONS POPUPS (ST's own lists, restyled) ═══ */
#options .options-content, #extensionsMenu {
  background: var(--theme-paper) !important; border: 1px solid var(--theme-ink); box-shadow: 0 18px 40px -24px rgba(0,0,0,.35);
  backdrop-filter: none; padding: 8px 0; min-width: 230px;
}
#options .options-content a {
  display: flex; align-items: center; padding: 9px 22px; gap: 0; color: var(--theme-ink); opacity: 1;
  font-family: var(--theme-ui); font-size: 13.5px; letter-spacing: .04em;
}
#options .options-content a i { display: none !important; }
#options .options-content a:hover { color: var(--theme-accent); background: var(--theme-page); }
#options .options-content hr { border: 0; border-top: 1px solid var(--theme-accent); margin: 8px 22px; opacity: 1; }

/* ✦ Extensions menu: titles only, all on one left edge, whatever icon an extension brings
   (same selectors core uses for the items, so equal specificity and ours wins) */
#extensionsMenu>.extension_container>div, #extensionsMenu>div:not(.extension_container), #extensionsMenu .list-group-item {
  align-items: center; justify-content: flex-start; column-gap: 0; gap: 0; margin: 0; padding: 9px 22px !important; text-indent: 0;
  width: 100%; box-sizing: border-box; text-align: left; background: none; border: 0; opacity: 1;
  font-family: var(--theme-ui); font-size: 13.5px; letter-spacing: .04em; color: var(--theme-ink);
}
#extensionsMenu>.extension_container>div *, #extensionsMenu>div:not(.extension_container) * { margin-left: 0; padding-left: 0; font-family: inherit; font-size: inherit; color: inherit; }
#extensionsMenu :is(i, img, svg, .extensionsMenuExtensionButton, [class*="fa-"]:empty) { display: none !important; }
#extensionsMenu>.extension_container>div::before, #extensionsMenu>div:not(.extension_container)::before { content: none !important; }
#extensionsMenu>.extension_container>div:hover, #extensionsMenu>div:not(.extension_container):hover { color: var(--theme-accent); background: var(--theme-page); }

/* ═══ LOADING SCREEN: a folio number turning pages ═══
   ST builds #loader.splash-screen > img.splash-logo + #load-spinner (a spinning gear) + h2.splash-message;
   everyday loaders are #loader > #load-spinner alone. Same markup, restyled: no logo, no gear. */
.popup:has(#loader)::backdrop { background-color: color-mix(in srgb, var(--theme-page) 96%, transparent); backdrop-filter: none; }
#loader .splash-logo { display: none; }
#loader #load-spinner {
  display: block; font-size: 64px; width: 1.3em; height: 1em; line-height: 1; overflow: hidden; animation: none; --spinner-size: 1em;
}
#loader:not(.splash-screen) #load-spinner { left: calc(50% - .65em); top: calc(50% - .5em); }
#loader #load-spinner::before {
  content: "01\A 02\A 03\A 04\A 05\A 01"; white-space: pre; display: block;
  font-family: var(--theme-display); font-weight: 400; font-style: normal; color: var(--theme-num); font-variant-numeric: lining-nums;
  animation: theme-folio-flip 4.2s cubic-bezier(.7, 0, .2, 1) infinite;
}
#loader.splash-screen {
  display: grid; grid-template-columns: auto 1px auto; grid-template-rows: auto auto; column-gap: 18px; row-gap: 8px;
  align-content: center; justify-content: center; align-items: end;
}
#loader.splash-screen #load-spinner { grid-row: 1 / 3; grid-column: 1; align-self: center; }
#loader.splash-screen::after { content: ""; grid-row: 1 / 3; grid-column: 2; align-self: stretch; background: var(--theme-rule); }
#loader.splash-screen::before {
  content: "Folio"; grid-row: 1; grid-column: 3; font-family: var(--theme-display); font-size: 32px; line-height: 1; color: var(--theme-ink);
}
#loader .splash-message {
  grid-row: 2; grid-column: 3; align-self: start; margin: 0;
  font-family: var(--theme-ui); font-size: 12px; font-weight: 400; letter-spacing: .08em; color: var(--theme-grey); opacity: 1;
}
@keyframes theme-folio-flip {
  0%, 14%  { transform: translateY(0); }
  20%, 34% { transform: translateY(-1em); }
  40%, 54% { transform: translateY(-2em); }
  60%, 74% { transform: translateY(-3em); }
  80%, 94% { transform: translateY(-4em); }
  100%     { transform: translateY(-5em); }
}
@media (prefers-reduced-motion: reduce) { #loader #load-spinner::before { animation: none; } }

/* ═══ CHINESE / JAPANESE / KOREAN INTERFACE ═══
   ST sets <html lang> from your language. Wide letter-spacing suits small Latin capitals,
   but CJK text isn't written with gaps between characters, so captions tighten up. */
:root:is(:lang(zh), :lang(ja), :lang(ko)) :is(
  .drawer-content h4, .drawer-content h5, .standoutHeader, #user-settings-block h4,
  #extensions_settings .inline-drawer-header, #extensions_settings2 .inline-drawer-header,
  .tag, .BGSampleTitle, #chat .mes .timestamp, #chat .mes .mes_reasoning_header_title, #chat .mes.smallSysMes .mes_text
) { letter-spacing: .02em; }

/* ═══ MODES THE USER CAN SWITCH ON ═══ */
/* Chat Style: Bubbles — keep the page, drop core's rounded cards */
body.bubblechat #chat .mes { border: 0; border-radius: 0; margin-bottom: 0; }
/* Chat Style: Document — no photographs, avatars or names (core hides them) */
body.documentstyle #chat .mes { --theme-photo: 0px; }
body.documentstyle #chat .mes .mesAvatarWrapper { display: none !important; }
body.documentstyle #chat .mes::before { display: none; }
/* Hide Chat Avatars — the photograph stays, just without the portrait */
/* Avatar Style: Rectangle — taller portrait still fits the photograph */
body.big-avatars #chat .mes { --avatar-base-width: 94px; --avatar-base-height: 94px; } /* core ×1.2 / ×1.8 → 113 × 169, same presence as the 128 square */
/* Visual Novel mode — sprites must stay visible, so no paper around the column */
body.waifuMode #sheld { box-shadow: none; }
/* Fast UI (no-blur) removes blur from elements, not from the photograph's pseudo-element,
   so the photograph stays fogged in both modes. */

/* ═══ PHONE (ST switches to its mobile layout under 1000px) ═══ */
@media screen and (max-width: 1000px) {
  :root { --theme-m: 14px; --theme-photo: 200px; --theme-numcol: var(--theme-left-phone); --theme-text-right: var(--theme-text-right-phone); }
  #chat .mes { --avatar-base-width: 104px; --avatar-base-height: 104px; grid-template-columns: var(--theme-m) minmax(var(--theme-numcol), max-content) 14px minmax(0, 1fr) var(--theme-m); }
  #chat .mes .mesIDDisplay { font-size: 22px; }
  #chat .mes .name_text { font-size: 25px; }
  #chat .mes .timestamp { letter-spacing: .14em; font-size: 9.5px; }
  #chat .mes .mes_text { font-size: calc(var(--mainFontSize) * 1.07); }
  #chat .mes .mes_timer, #chat .mes .tokenCounterDisplay { font-size: 9px; }
  /* phone: tools appear when you tap a message (with its date and tokens), folio-quiet */
  #chat .mes .mes_buttons { border-color: var(--theme-rule); }
  #chat .mes .ch_name > .flex-container { padding-bottom: 4px; }
  #leftSendForm, #rightSendForm { width: auto; flex-wrap: nowrap; flex-direction: row; }
  #chat .mes .mes_buttons { max-width: calc(100% - 24px); flex-wrap: wrap; justify-content: flex-end; }
  #chat .mes .extraMesButtons.visible { flex-wrap: wrap !important; }
  #chat .mes .mes_button { width: 36px; height: 40px; line-height: 40px; }
  body.big-avatars #chat .mes { --avatar-base-width: 76px; --avatar-base-height: 76px; } /* → 91 × 137 */
  #chat .mes[is_user="true"] .name_text { font-size: 21px; }
  #top-settings-holder .drawer-icon { --theme-ic: 20px; }
  .drawer-content { border-left: 0; border-right: 0; padding: 12px 14px; }
  /* a full-screen panel covers the chat: stop the photographs' blur underneath so the panel opens smoothly */
  body:has(.drawer-content.openDrawer) #chat .mes::before { backdrop-filter: none; -webkit-backdrop-filter: none; }
}
